const fs=require('fs'),cp=require('child_process'),crypto=require('crypto');
const OLD_COMMIT='e36184f1e46731004401f930da59c74740fab933',OLD_META='55499700d4e760671573c7e476a3709d08a9aa3aeb4ce8ce7861ee7f40d36909',NEW_META='25d1032044996d2eed8cab3b2c9d6bfbfab91349f0ac6e49ef168c307654b24f',TEXT_SEQ='e1040127a9bd9221d685092edee930cf7183c0ed3ce2aaea6fa6dd64174b3488';
