function run(script){fs.rmSync('wip-current-semantic-pack',{recursive:true,force:true});cp.execFileSync(process.execPath,[script],{stdio:['ignore','pipe','inherit'],maxBuffer:32*1024*1024});return fs.readFileSync('wip-current-semantic-pack/metadata.jsonl');}
