ok(sha(old)===OLD_META,'OLD_METADATA_HASH');
const A=old.toString('utf8').trimEnd().split(/\r?\n/).map(JSON.parse),B=current.toString('utf8').trimEnd().split(/\r?\n/).map(JSON.parse);ok(A.length===B.length&&A.length===22873,'ROW_COUNT');
