function feed(h,s){const b=Buffer.from(String(s),'utf8'),len=Buffer.alloc(8);len.writeBigUInt64BE(BigInt(b.length));h.update(len);h.update(b);}
for(let i=0;i<A.length;i++){const a=A[i],b=B[i];feed(th1,a.text);feed(th2,b.text);const aa=Object.fromEntries(Object.entries(a).filter(([k])=>!ignore.has(k))),bb=Object.fromEntries(Object.entries(b).filter(([k])=>!ignore.has(k)));if(JSON.stringify(aa)!==JSON.stringify(bb)){mismatches++;if(examples.length<10)examples.push({row:i,old_id:a.passage_id,new_id:b.passage_id});}ok(a.passage_id==='E-96-72-'+String(i+1).padStart(6,'0'),'OLD_ID '+i);ok(b.passage_id==='PLS16-E-96-72-'+String(i+1).padStart(6,'0'),'NEW_ID '+i);ok(a.chunk_policy_id==='96-72'&&b.chunk_policy_id==='96-72-current-v14215-r1','POLICY_ID '+i);}
